using MySqlConnector;
using OnlineElectronicSellingSystem.Data;
using OnlineElectronicSellingSystem.Models;

namespace OnlineElectronicSellingSystem.Repositories;

public sealed class SupplierRepository
{
    private readonly Database database;
    public SupplierRepository(Database database)=>this.database=database;
    public IReadOnlyList<SupplierManagementRecord> Suppliers(){using var c=database.OpenConnection();using var cmd=new MySqlCommand("SELECT id,name,contact_name,email,phone,address,is_active FROM suppliers ORDER BY name",c);using var r=cmd.ExecuteReader();var a=new List<SupplierManagementRecord>();while(r.Read())a.Add(new SupplierManagementRecord{Id=r.GetInt32("id"),Name=r.GetString("name"),ContactName=r.IsDBNull(r.GetOrdinal("contact_name"))?null:r.GetString("contact_name"),Email=r.IsDBNull(r.GetOrdinal("email"))?null:r.GetString("email"),Phone=r.IsDBNull(r.GetOrdinal("phone"))?null:r.GetString("phone"),Address=r.IsDBNull(r.GetOrdinal("address"))?null:r.GetString("address"),IsActive=r.GetBoolean("is_active")});return a;}
    public void SaveSupplier(SupplierManagementRecord s){using var c=database.OpenConnection();using var cmd=new MySqlCommand(@"INSERT INTO suppliers(name,contact_name,email,phone,address,is_active) VALUES(@name,@contact,@email,@phone,@address,@active) ON DUPLICATE KEY UPDATE contact_name=@contact,email=@email,phone=@phone,address=@address,is_active=@active",c);cmd.Parameters.AddWithValue("@name",s.Name.Trim());cmd.Parameters.AddWithValue("@contact",(object?)s.ContactName??DBNull.Value);cmd.Parameters.AddWithValue("@email",(object?)s.Email??DBNull.Value);cmd.Parameters.AddWithValue("@phone",(object?)s.Phone??DBNull.Value);cmd.Parameters.AddWithValue("@address",(object?)s.Address??DBNull.Value);cmd.Parameters.AddWithValue("@active",s.IsActive);cmd.ExecuteNonQuery();}
    public IReadOnlyList<PurchaseOrderRecord> PurchaseOrders(){using var c=database.OpenConnection();using var cmd=new MySqlCommand("SELECT po.id,po.supplier_id,s.name,po.purchase_order_number,po.status,po.ordered_at,po.received_at,po.notes FROM purchase_orders po JOIN suppliers s ON s.id=po.supplier_id ORDER BY po.id DESC",c);using var r=cmd.ExecuteReader();var a=new List<PurchaseOrderRecord>();while(r.Read())a.Add(new PurchaseOrderRecord{Id=r.GetInt32("id"),SupplierId=r.GetInt32("supplier_id"),SupplierName=r.GetString("name"),PurchaseOrderNumber=r.GetString("purchase_order_number"),Status=r.GetString("status"),OrderedAt=r.IsDBNull(r.GetOrdinal("ordered_at"))?null:r.GetDateTime("ordered_at"),ReceivedAt=r.IsDBNull(r.GetOrdinal("received_at"))?null:r.GetDateTime("received_at"),Notes=r.IsDBNull(r.GetOrdinal("notes"))?null:r.GetString("notes")});return a;}
    public void UpdatePurchaseOrderStatus(int id,string status){using var c=database.OpenConnection();using var cmd=new MySqlCommand("UPDATE purchase_orders SET status=@status,ordered_at=IF(@status='Ordered',COALESCE(ordered_at,CURRENT_TIMESTAMP),ordered_at),received_at=IF(@status='Received',COALESCE(received_at,CURRENT_TIMESTAMP),received_at) WHERE id=@id",c);cmd.Parameters.AddWithValue("@status",status);cmd.Parameters.AddWithValue("@id",id);cmd.ExecuteNonQuery();}
    public void CreatePurchaseOrder(int supplierId,string number,int productId,int quantity,decimal unitCost,string? notes){if(quantity<1||unitCost<0)throw new ArgumentException("Quantity and unit cost must be valid.");using var c=database.OpenConnection();using var t=c.BeginTransaction();try{using var h=new MySqlCommand("INSERT INTO purchase_orders(supplier_id,purchase_order_number,status,notes) VALUES(@supplier,@number,'Draft',@notes); SELECT LAST_INSERT_ID();",c,t);h.Parameters.AddWithValue("@supplier",supplierId);h.Parameters.AddWithValue("@number",number.Trim());h.Parameters.AddWithValue("@notes",(object?)notes??DBNull.Value);var id=Convert.ToInt32(h.ExecuteScalar());using var i=new MySqlCommand("INSERT INTO purchase_order_items(purchase_order_id,product_id,quantity,unit_cost) VALUES(@order,@product,@quantity,@cost)",c,t);i.Parameters.AddWithValue("@order",id);i.Parameters.AddWithValue("@product",productId);i.Parameters.AddWithValue("@quantity",quantity);i.Parameters.AddWithValue("@cost",unitCost);i.ExecuteNonQuery();t.Commit();}catch{t.Rollback();throw;}}
}
